import json

def recover_relations(response: str, atoms: dict[str, str]) -> list:
    """
    Recover logical relations between atoms in a response.

    Args:
    response (str): The response to analyze.
    atoms (dict[str, str]): A dictionary mapping atom numbers to their text.

    Returns:
    list: A list of dictionaries representing the logical relations between atoms.
    """

    relations = []

    # Cause-Effect relations
    if "as a result" in response or "because" in response:
        if "7" in atoms and "8" in atoms:
            relations.append({
                "source": 7,
                "target": 8,
                "sense": "Cause-Effect",
                "coupling": "entailment",
                "strength_band": "strong"
            })

    # Evidence relations
    if "shows" in response or "indicates" in response:
        if "2" in atoms and "4" in atoms:
            relations.append({
                "source": 2,
                "target": 4,
                "sense": "Evidence",
                "coupling": "entailment",
                "strength_band": "strong"
            })
        if "13" in atoms and "11" in atoms:
            relations.append({
                "source": 13,
                "target": 11,
                "sense": "Evidence",
                "coupling": "entailment",
                "strength_band": "strong"
            })

    # Restatement relations
    if "that is" in response or "in other words" in response:
        if "3" in atoms and "4" in atoms:
            relations.append({
                "source": 3,
                "target": 4,
                "sense": "Restatement",
                "coupling": "equivalence",
                "strength_band": "strong"
            })

    # Refutation relations
    if "cannot both be true" in response:
        if "9" in atoms and "10" in atoms:
            relations.append({
                "source": 9,
                "target": 10,
                "sense": "Refutation",
                "coupling": "contradiction",
                "strength_band": "strong"
            })
        if "4" in atoms and "5" in atoms:
            relations.append({
                "source": 4,
                "target": 5,
                "sense": "Refutation",
                "coupling": "contradiction",
                "strength_band": "strong"
            })

    # Contrast relations
    if "by contrast" in response or "whereas" in response:
        if "9" in atoms and "10" in atoms:
            relations.append({
                "source": 9,
                "target": 10,
                "sense": "Contrast",
                "coupling": "none",
                "strength_band": "moderate"
            })

    # Concession relations
    if "although" in response or "despite" in response:
        if "9" in atoms and "10" in atoms:
            relations.append({
                "source": 9,
                "target": 10,
                "sense": "Concession",
                "coupling": "none",
                "strength_band": "moderate"
            })

    # Alternative relations
    if "exactly one of" in response:
        if "4" in atoms and "5" in atoms:
            relations.append({
                "source": 4,
                "target": 5,
                "sense": "Alternative",
                "coupling": "exclusive",
                "strength_band": "strong"
            })

    # Disjunction relations
    if "at least one of" in response:
        if "12" in atoms and "13" in atoms:
            relations.append({
                "source": 12,
                "target": 13,
                "sense": "Disjunction",
                "coupling": "co_necessity",
                "strength_band": "moderate"
            })

    # Precedence relations
    if "before" in response:
        if "1" in atoms and "2" in atoms:
            relations.append({
                "source": 1,
                "target": 2,
                "sense": "Precedence",
                "coupling": "none",
                "strength_band": "moderate"
            })

    # Succession relations
    if "after" in response:
        if "2" in atoms and "3" in atoms:
            relations.append({
                "source": 2,
                "target": 3,
                "sense": "Succession",
                "coupling": "none",
                "strength_band": "moderate"
            })

    return relations

